import {presentButton} from './interface.mjs';
import {openNews} from './profile-links.mjs';
export function initNotifications(c){const {$,state,req,element,button,toast}=c;const rpc=(action,payload={})=>req('/rest/v1/rpc/push_action',{method:'POST',body:{action,payload}});let publicKey;const ready=()=>Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(new Error('تعذّر تجهيز الإشعارات. حدّث التطبيق وحاول مجددًا.')),6000))]);const section=element('section');section.id='notification-settings';section.innerHTML='<h3>إشعارات الجوال</h3><p class="muted">تنبيهات عامة دون عرض أسماء أو نص الرسائل على شاشة القفل. على الآيفون: افتح النسخة المضافة إلى الشاشة الرئيسية. قد يتأخر وصول التنبيه بحسب الجهاز وحجم الإرسال.</p><label class="inline"><input id="notify-news" type="checkbox" checked> الأخبار الجديدة</label><label class="inline"><input id="notify-private" type="checkbox" checked> الرسائل الخاصة الواردة</label><label class="inline"><input id="notify-follows" type="checkbox" checked> الحسابات التي أتابعها والمنشن</label><p id="notify-status" role="status"></p>';$('profile-dialog').append(section);const enable=button('🔔 تفعيل الإشعارات على هذا الجهاز',activate,'secondary'),disable=button('إيقاف إشعارات هذا الجهاز',deactivate,'text-button');enable.id='notifications-enable';disable.id='notifications-disable';section.append(enable,disable);
 function supported(){return 'Notification'in globalThis&&'serviceWorker'in navigator&&'PushManager'in globalThis;}
 function bytes(s){const raw=atob(s.replace(/-/g,'+').replace(/_/g,'/'));return Uint8Array.from(raw,c=>c.charCodeAt(0));}
 async function load(){await refreshInbox().catch(()=>{});enable.hidden=disable.hidden=state.profile?.status!=='active';if(!supported()){$('notify-status').textContent='الإشعارات غير مدعومة هنا. استخدم متصفحًا داعمًا؛ وعلى الآيفون افتح التطبيق من الشاشة الرئيسية.';return;}const k=await rpc('key');publicKey=k.publicKey;$('notify-status').textContent=Notification.permission==='granted'?'يمكن تفعيل الإشعارات أو حفظ اختياراتك لهذا الجهاز.':Notification.permission==='denied'?'الإذن مرفوض. غيّر إذن الإشعارات من إعدادات الجهاز إذا رغبت.':'اضغط تفعيل الإشعارات للموافقة من الجهاز.';}
 async function activate(){if(!supported())throw new Error('افتح التطبيق من الشاشة الرئيسية على الآيفون، أو من متصفح يدعم الإشعارات.');if(state.profile?.status!=='active')throw new Error('الإشعارات للأعضاء المعتمدين.');const permission=await Notification.requestPermission();if(permission!=='granted')throw new Error('لم تمنح الجهاز إذن الإشعارات.');if(!publicKey)publicKey=(await rpc('key')).publicKey;const registration=await ready();let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes(publicKey)});await rpc('subscribe',{subscription:subscription.toJSON(),news:$('notify-news').checked,private_chat:$('notify-private').checked,follow_alerts:$('notify-follows').checked});$('notify-status').textContent='الإشعارات مفعّلة على هذا الجهاز.';toast('تم تفعيل الإشعارات وحفظ اختياراتك.');}
 async function deactivate(){if(!supported())return;const registration=await ready(),subscription=await registration.pushManager.getSubscription();if(subscription){try{if(state.user)await rpc('unsubscribe',{endpoint:subscription.endpoint});}finally{await subscription.unsubscribe();}}$('notify-status').textContent='إشعارات هذا الجهاز موقوفة.';}
 const bell=button('♧',()=>openInbox(),'icon-only');presentButton(bell,'bell','الإشعارات',{iconOnly:true});bell.id='notification-bell';bell.hidden=true;bell.setAttribute('aria-label','الإشعارات');bell.dataset.count='0';document.getElementById('header-actions').prepend(bell);let inbox=null,inboxData=null,epoch=0;
 async function refreshInbox(){if(!state.user||state.profile?.status!=='active'){bell.hidden=true;return}const identity=state.user.id,n=epoch;const data=await req('/rest/v1/rpc/native_notifications',{method:'POST',body:{action:'list',payload:{}}});if(identity!==state.user?.id||n!==epoch)return;inboxData=data;bell.hidden=false;const unread=(data.items||[]).filter(x=>Date.parse(x.created_at)>Date.parse(data.read_at)).length;bell.dataset.count=String(unread>99?'99+':unread);bell.setAttribute('aria-label','الإشعارات · '+unread+' غير مقروءة');if(inbox?.open)paintInbox()}
 function paintInbox(){if(!inbox?.open||!inboxData)return;const box=inbox.querySelector('.notification-list');box.replaceChildren();for(const item of inboxData.items||[]){const b=button('',()=>{inbox.close();inbox.remove();inbox=null;if(item.kind==='news')openNews(item.post_id);else document.dispatchEvent(new CustomEvent('family:chat',{detail:{id:item.member_id}}))},'notification-row'+(Date.parse(item.created_at)>Date.parse(inboxData.read_at)?' unread':''));b.append(element('span',item.kind==='news'?'▤':'◌'),element('span',item.kind==='news'?item.title:'رسالة خاصة من '+item.title),element('small',new Date(item.created_at).toLocaleDateString('ar-SA')));box.append(b)}if(!box.children.length)box.append(element('p','لا توجد إشعارات بعد.'))}
 async function openInbox(){inbox=element('dialog',undefined,'notification-center');const close=button('إغلاق',()=>{inbox.close();inbox.remove();inbox=null});const mark=button('قراءة الكل',async()=>{try{if(inboxData?.server_at)await req('/rest/v1/rpc/native_notifications',{method:'POST',body:{action:'read',payload:{through:inboxData.server_at}}});await refreshInbox()}catch(e){toast(e.message)}});inbox.append(element('h2','الإشعارات'),close,mark,element('div',undefined,'notification-list'));document.body.append(inbox);inbox.showModal();try{await refreshInbox();paintInbox()}catch(e){toast(e.message)}}
 const inboxTimer=setInterval(()=>{if(state.user&&!document.hidden)refreshInbox().catch(()=>{})},30000);inboxTimer.unref?.();
 return {load,beforeLogout:async()=>{epoch++;bell.hidden=true;bell.dataset.count='0';inboxData=null;if(inbox){inbox.close();inbox.remove();inbox=null}await deactivate()}};
}
